'use client';
import { useEffect, useState } from 'react';
import { Button } from './Button';

const STORAGE_KEY = 'vendcota-theme';

/**
 * Hook de tema. Lê preferência salva → prefers-color-scheme → 'light'.
 * Aplica via `data-theme` no <html>, que é o seletor que tokens.css espera.
 */
export function useTheme() {
  const [theme, setTheme] = useState<'light' | 'dark'>('light');

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY) as 'light' | 'dark' | null;
    const preferred = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    const initial = saved ?? preferred;
    setTheme(initial);
    document.documentElement.setAttribute('data-theme', initial);
  }, []);

  function toggle() {
    const next = theme === 'dark' ? 'light' : 'dark';
    setTheme(next);
    document.documentElement.setAttribute('data-theme', next);
    localStorage.setItem(STORAGE_KEY, next);
  }

  return { theme, toggle };
}

export function ThemeToggle() {
  const { toggle } = useTheme();
  return (
    <Button variant="icon" aria-label="Alternar tema" onClick={toggle}>
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
        <path d="M12 3a9 9 0 1 0 9 9c0-.5 0-1-.1-1.4A5.5 5.5 0 0 1 12.4 3.1 9 9 0 0 0 12 3z" />
      </svg>
    </Button>
  );
}
